-- Isolated rollback fixtures: no actual user data, supplier actions or payment.
BEGIN;
CREATE FUNCTION pg_temp.chat_assert(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'TEST FAILED: %',label;END IF;END$$;
DO $$
<<fixture>>
DECLARE u uuid:=gen_random_uuid();other_user uuid:=gen_random_uuid();root_id uuid:=gen_random_uuid();hid uuid:=gen_random_uuid();cid uuid;
 req uuid:=gen_random_uuid();req2 uuid:=gen_random_uuid();pid uuid:=gen_random_uuid();apply_id uuid:=gen_random_uuid();inp jsonb;plan jsonb;proposal jsonb;changed jsonb;a jsonb;b jsonb;first_lease uuid;second_lease uuid;source_time timestamptz;failed boolean;q jsonb;
BEGIN
 INSERT INTO auth.users(id,email,email_confirmed_at,raw_user_meta_data)VALUES(u,'chat-'||u||'@example.invalid',now(),'{}'),(other_user,'chat-'||other_user||'@example.invalid',now(),'{}');
 inp:=jsonb_build_object('city','Shanghai','date',current_date+80,'guests',1,'prompt','Shanghai food and museum','days',2,'dayStart','09:00','dayEnd','20:00','transport','walk');
 plan:='{"summary":"Two full days","stops":[{"id":"amap_chatoutdoor","dayIndex":1,"start":"09:00","end":"10:00","reason":"Visit"},{"id":"amap_chatlunch","dayIndex":1,"start":"12:00","end":"13:00","reason":"Lunch"},{"id":"amap_chatmuseum","dayIndex":2,"start":"09:00","end":"10:00","reason":"Museum"}]}';
 INSERT INTO journey_hub.trip_history(id,user_id,input,place_ids)VALUES(root_id,u,inp,ARRAY['amap_chatoutdoor','amap_chatlunch','amap_chatmuseum','amap_chatalternative']) RETURNING updated_at INTO source_time;
 PERFORM public.journeyhub_trip_snapshot_put(u,root_id,source_time,'{"schemaVersion":1,"places":[{"id":"amap_chatoutdoor","name":"River walk","kind":"sightseeing"},{"id":"amap_chatlunch","name":"Local lunch","kind":"restaurant"},{"id":"amap_chatmuseum","name":"Museum","kind":"museum"},{"id":"amap_chatalternative","name":"Indoor gallery","kind":"museum"}]}');
 INSERT INTO journey_hub.trip_history(id,user_id,parent_id,input,place_ids,plan)VALUES(hid,u,root_id,inp,ARRAY['amap_chatoutdoor','amap_chatlunch','amap_chatmuseum'],plan);
 a:=public.journeyhub_care_confirm(u,'history',hid);cid:=(a->>'id')::uuid;
 PERFORM pg_temp.chat_assert(public.journeyhub_care_chat_read(other_user,cid)IS NULL,'foreign account cannot read chat');
 failed:=false;BEGIN PERFORM public.journeyhub_care_chat_start(other_user,cid,req,'Hello',1);EXCEPTION WHEN OTHERS THEN failed:=SQLERRM='CARE_CHAT_NOT_FOUND';END;
 PERFORM pg_temp.chat_assert(failed,'foreign account cannot start chat');
 a:=public.journeyhub_care_chat_start(u,cid,req,'It is raining. Replace the river walk.',1);
 PERFORM pg_temp.chat_assert(a#>>'{conversation,pending,status}'='pending','pending survives response and refresh');
 a:=public.journeyhub_care_chat_start(u,cid,req,'It is raining. Replace the river walk.',1);
 PERFORM pg_temp.chat_assert(jsonb_array_length(a#>'{conversation,messages}')=1,'same request appends one user message');
 failed:=false;BEGIN PERFORM public.journeyhub_care_chat_start(u,cid,req,'Changed text',1);EXCEPTION WHEN OTHERS THEN failed:=SQLERRM='CARE_CHAT_REQUEST_CONFLICT';END;
 PERFORM pg_temp.chat_assert(failed,'request identity cannot be reused with other input');
 failed:=false;BEGIN PERFORM public.journeyhub_care_chat_start(u,cid,req2,'Another request',2);EXCEPTION WHEN OTHERS THEN failed:=SQLERRM='CARE_CHAT_BUSY';END;
 PERFORM pg_temp.chat_assert(failed,'single pending task per care');
 a:=public.journeyhub_care_chat_claim(u,cid,req);first_lease:=(a->>'lease')::uuid;
 PERFORM pg_temp.chat_assert(jsonb_array_length(a->'alternatives')=4,'all owned parent candidates available');
 PERFORM pg_temp.chat_assert(public.journeyhub_care_chat_claim(u,cid,req)IS NULL,'simultaneous claim does not duplicate work');
 UPDATE journey_hub.care_chat_requests SET lease_until=now()-interval '1 second' WHERE user_id=u AND request_id=req;
 a:=public.journeyhub_care_chat_claim(u,cid,req);second_lease:=(a->>'lease')::uuid;
 PERFORM pg_temp.chat_assert(second_lease<>first_lease,'expired lease resumes with a new fence');
 PERFORM pg_temp.chat_assert(public.journeyhub_care_chat_complete(u,cid,req,first_lease,'Old result',NULL,'[]')IS NULL,'old worker cannot commit after lease takeover');
 changed:=jsonb_set(plan,'{stops,0,id}','"amap_chatalternative"');
 changed:=jsonb_set(jsonb_set(changed,'{stops,0,lat}','31.23'),'{stops,0,lng}','121.47')||'{"roadRoutes":[{"fromId":"amap_chatalternative","toId":"amap_chatlunch","minutes":12,"distanceMeters":1800}]}'::jsonb;
 proposal:=jsonb_build_object('id',pid,'revision',1,'canApply',true,'expiresAt',now()+interval '30 minutes','plan',changed,'replacements',jsonb_build_array(jsonb_build_object('fromId','amap_chatoutdoor','toId','amap_chatalternative')));
 a:=public.journeyhub_care_chat_complete(u,cid,req,second_lease,'I found an indoor option. Review before applying.',proposal,'[{"tool":"saved_places","summary":"Checked saved alternatives"}]');
 PERFORM pg_temp.chat_assert(a#>'{conversation,pending}'='null'::jsonb AND jsonb_array_length(a#>'{conversation,messages}')=2,'completion persists user and assistant exactly once');
 PERFORM pg_temp.chat_assert(a#>>'{care,plan,stops,0,id}'='amap_chatoutdoor','proposal does not mutate trip');
 PERFORM pg_temp.chat_assert(a#>>'{conversation,messages,1,dayIndex}'='1','assistant retains selected day');
 a:=public.journeyhub_care_chat_apply(u,cid,pid,apply_id);
 PERFORM pg_temp.chat_assert(a#>>'{care,plan,stops,0,id}'='amap_chatalternative' AND a#>>'{care,revision}'='2','explicit apply substitutes saved candidate');
 PERFORM pg_temp.chat_assert(a#>>'{care,plan,stops,0,lat}'='31.23' AND a#>>'{care,plan,roadRoutes,0,minutes}'='12','accepted provider metadata and road routes hydrate');
 PERFORM pg_temp.chat_assert((SELECT NOT(c.plan ? 'roadRoutes') AND NOT(c.plan->'stops'->0 ? 'lat') FROM journey_hub.trip_care c WHERE c.id=cid),'canonical schedule does not retain provider material');
 PERFORM pg_temp.chat_assert(EXISTS(SELECT FROM jsonb_array_elements(a#>'{care,places}')p WHERE p->>'id'='amap_chatalternative'),'replacement label survives read');
 PERFORM pg_temp.chat_assert((SELECT h.plan=fixture.plan FROM journey_hub.trip_history h WHERE h.id=hid),'original saved history unchanged');
 a:=public.journeyhub_care_chat_apply(u,cid,pid,apply_id);b:=public.journeyhub_care_chat_apply(u,cid,pid,gen_random_uuid());
 PERFORM pg_temp.chat_assert(a#>>'{care,revision}'='2' AND b#>>'{care,revision}'='2','repeated apply never changes revision twice');
 PERFORM pg_temp.chat_assert((SELECT count(*)=1 FROM journey_hub.care_chat_applies WHERE care_id=cid),'only one applied confirmation');
 UPDATE journey_hub.care_chat_place_cache SET revision=999 WHERE care_id=cid;
 a:=public.journeyhub_care_chat_read(u,cid);
 PERFORM pg_temp.chat_assert(a#>>'{care,plan,stops,0,lat}' IS NULL,'cache from wrong revision never hydrates');
 UPDATE journey_hub.care_chat_place_cache SET revision=2,expires_at=now()-interval '1 second' WHERE care_id=cid;
 DELETE FROM journey_hub.trip_display_snapshots WHERE history_id=root_id;
 a:=public.journeyhub_care_chat_read(u,cid);
 PERFORM pg_temp.chat_assert(a#>>'{care,plan,stops,0,lat}' IS NULL AND a#>>'{care,plan,stops,0,start}'='09:00','cache expiry preserves canonical times');
 PERFORM pg_temp.chat_assert(EXISTS(SELECT FROM jsonb_array_elements(a#>'{care,places}')p WHERE p->>'id'='amap_chatalternative' AND p->>'name'='Indoor gallery'),'accepted English labels survive source snapshot invalidation');
 PERFORM journey_hub.planner_task_cleanup();
 PERFORM pg_temp.chat_assert(NOT EXISTS(SELECT FROM journey_hub.care_chat_place_cache WHERE care_id=cid),'existing cleanup deletes expired provider cache');
 -- Arbitrary IDs and unexplained substitutions are never accepted.
 pid:=gen_random_uuid();proposal:=jsonb_set(proposal,'{id}',to_jsonb(pid::text));proposal:=jsonb_set(proposal,'{revision}','2');
 proposal:=jsonb_set(proposal,'{plan,stops,0,id}','"amap_unowned"');proposal:=jsonb_set(proposal,'{replacements}','[{"fromId":"amap_chatalternative","toId":"amap_unowned"}]');
 PERFORM public.journeyhub_care_update(u,cid,2,NULL,proposal);
 failed:=false;BEGIN PERFORM public.journeyhub_care_accept(u,cid,pid);EXCEPTION WHEN OTHERS THEN failed:=SQLERRM='CARE_UNSAFE_ADJUSTMENT';END;
 PERFORM pg_temp.chat_assert(failed,'unowned new venue rejected');
 proposal:=jsonb_set(proposal,'{plan}',changed);proposal:=jsonb_set(proposal,'{replacements}','[]');
 proposal:=jsonb_set(proposal,'{plan,stops,2,dayIndex}','1');proposal:=jsonb_set(proposal,'{plan,stops,2,start}','"15:00"');proposal:=jsonb_set(proposal,'{plan,stops,2,end}','"16:00"');
 PERFORM public.journeyhub_care_update(u,cid,2,NULL,proposal);
 failed:=false;BEGIN PERFORM public.journeyhub_care_accept(u,cid,pid);EXCEPTION WHEN OTHERS THEN failed:=SQLERRM='CARE_UNSAFE_ADJUSTMENT';END;
 PERFORM pg_temp.chat_assert(failed,'empty day rejected');
 -- In-flight answer cannot overwrite an accepted newer revision.
 a:=public.journeyhub_care_chat_start(u,cid,req2,'Check my lunch timing',1);
 PERFORM pg_temp.chat_assert(a#>'{care,proposal}'='null'::jsonb,'new chat abandons previous unapplied proposal');
 a:=public.journeyhub_care_chat_claim(u,cid,req2);first_lease:=(a->>'lease')::uuid;
 UPDATE journey_hub.trip_care SET revision=revision+1,proposal=NULL WHERE id=cid;
 a:=public.journeyhub_care_chat_complete(u,cid,req2,first_lease,'Stale answer',NULL,'[]');
 PERFORM pg_temp.chat_assert(a#>>'{conversation,pending,status}'='failed','revision changed answer fails safely');
 a:=public.journeyhub_care_chat_start(u,cid,req2,'Check my lunch timing',1);a:=public.journeyhub_care_chat_claim(u,cid,req2);first_lease:=(a->>'lease')::uuid;
 a:=public.journeyhub_care_chat_fail(u,cid,req2,first_lease,'Service unavailable. Retry.');
 PERFORM pg_temp.chat_assert(a#>>'{conversation,pending,message}'='Service unavailable. Retry.','safe retry failure saved');
 -- Canonical booking is checked at acceptance, including late payment.
 PERFORM public.journeyhub_demo_wallet_topup(u,100000,gen_random_uuid());
 q:=public.journeyhub_demo_quote_save(u,'history',hid,'[{"stopId":"amap_chatalternative","kind":"ticket","unitMinor":4000,"displayTitle":"Indoor gallery"},{"stopId":"amap_chatlunch","kind":"restaurant","unitMinor":5000,"displayTitle":"Local lunch"},{"stopId":"amap_chatmuseum","kind":"ticket","unitMinor":4000,"displayTitle":"Museum"}]');
 PERFORM public.journeyhub_demo_book(u,(q->>'id')::uuid,gen_random_uuid());
 pid:=gen_random_uuid();proposal:=jsonb_build_object('id',pid,'revision',3,'canApply',true,'expiresAt',now()+interval '30 minutes','plan',jsonb_set(jsonb_set(changed,'{stops,1,start}','"12:30"'),'{stops,1,end}','"13:30"'));
 PERFORM public.journeyhub_care_update(u,cid,3,NULL,proposal);
 failed:=false;BEGIN PERFORM public.journeyhub_care_accept(u,cid,pid);EXCEPTION WHEN OTHERS THEN failed:=SQLERRM='CARE_RESERVATION_PROTECTED';END;
 PERFORM pg_temp.chat_assert(failed,'confirmed reservation cannot be moved');
 PERFORM pg_temp.chat_assert(NOT has_table_privilege('authenticated','journey_hub.care_chat_requests','SELECT') AND NOT has_function_privilege('authenticated','public.journeyhub_care_chat_start(uuid,uuid,uuid,text,integer)','EXECUTE'),'browser cannot spoof owner');
 PERFORM pg_temp.chat_assert((SELECT relrowsecurity FROM pg_class WHERE oid='journey_hub.care_chat_requests'::regclass),'chat table has RLS');
 RAISE NOTICE 'PASS trip chat: ownership, idempotency, refresh/retry, fenced takeover, saved substitutions, apply-once, preserved history/days and booking protection';
END$$;
ROLLBACK;
